python3 - > /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/lists_body.py <<'EOF'
import re
rec=open('explorations/coordinator/CLIMB-BATCH-27.md',encoding='utf-8').read()
s1=rec[rec.index('\n## 1. '):rec.index('\n## 2. ')]
SRC='ProjectFortress/src/com/sun/fortress/'
def keyexpr(k):
    if k=="REC `The planner's probes`": return 'PROBES'
    if k=='REC `Forks the batch takes, none consequential`': return 'FORKS'
    if k.startswith('REC `'): return 'REC + ' + repr(k[5:-1])
    k=k.strip('`')
